     4→using System;
     5→using System.Buffers.Binary;
     6→using System.Diagnostics;
     7→using System.Runtime.CompilerServices;
     8→using System.Runtime.InteropServices;
     9→using System.Runtime.Intrinsics;
    10→using Nethermind.Core;
    11→using Nethermind.Core.Extensions;
    12→using Nethermind.Core.Specs;
    13→using Nethermind.GmpBindings;
    14→using Nethermind.Int256;
    15→
    16→namespace Nethermind.Evm.Precompiles;
    17→
    18→/// <summary>
    19→/// https://github.com/ethereum/EIPs/blob/vbuterin-patch-2/EIPS/bigint_modexp.md
    20→/// </summary>
    21→public class ModExpPrecompile : IPrecompile<ModExpPrecompile>
    22→{
    23→    public static readonly ModExpPrecompile Instance = new();
    24→    /// <summary>
    25→    /// Maximum input size (in bytes) for the modular exponentiation operation under EIP-7823.
    26→    /// This constant defines the upper limit for the size of the input data that can be processed.
    27→    /// For more details, see: https://eips.ethereum.org/EIPS/eip-7823
    28→    /// </summary>
    29→    public const uint ModExpMaxInputSizeEip7823 = 1024;
    30→
    31→    private const int LengthSize = 32;
    32→    private const int StartBaseLength = 0;
    33→    private const int StartExpLength = 32;
    34→    private const int StartModLength = 64;
    35→    private const int LengthsLengths = StartModLength + LengthSize;
    36→
    37→    private ModExpPrecompile()
    38→    {
    39→    }
    40→
    41→    public static Address Address { get; } = Address.FromNumber(5);
    42→
    43→    public static string Name => "MODEXP";
    44→
    45→    public long BaseGasCost(IReleaseSpec releaseSpec) => 0L;
    46→
    47→    /// <summary>
    48→    /// https://github.com/ethereum/EIPs/pull/2892
    49→    /// ADJUSTED_EXPONENT_LENGTH is defined as follows.
    50→    /// If length_of_EXPONENT &lt;= 32, and all bits in EXPONENT are 0, return 0
    51→    /// If length_of_EXPONENT &lt;= 32, then return the index of the highest bit in EXPONENT (eg. 1 -> 0, 2 -> 1, 3 -> 1, 255 -> 7, 256 -> 8).
    52→    /// If length_of_EXPONENT > 32, then return 8 * (length_of_EXPONENT - 32) plus the index of the highest bit in the first 32 bytes of EXPONENT (eg. if EXPONENT = \x00\x00\x01\x00.....\x00, with one hundred bytes, then the result is 8 * (100 - 32) + 253 = 797). If all of the first 32 bytes of EXPONENT are zero, return exactly 8 * (length_of_EXPONENT - 32).
    53→    /// </summary>
    54→    /// <param name="inputData"></param>
    55→    /// <param name="releaseSpec"></param>
    56→    /// <returns>Gas cost of the MODEXP operation in the context of EIP2565</returns>
    57→    public long DataGasCost(ReadOnlyMemory<byte> inputData, IReleaseSpec releaseSpec)
    58→    {
    59→        if (!releaseSpec.IsEip2565Enabled)
    60→        {
    61→#pragma warning disable 618
    62→            return ModExpPrecompilePreEip2565.Instance.DataGasCost(inputData, releaseSpec);
    63→#pragma warning restore 618
    64→        }
    65→
    66→        try
    67→        {
    68→            ReadOnlySpan<byte> span = inputData.Span;
    69→            return span.Length >= LengthsLengths
    70→                ? DataGasCostInternal(span, releaseSpec)
    71→                : DataGasCostShortInternal(span, releaseSpec);
    72→        }
    73→        catch (OverflowException)
    74→        {
    75→            return long.MaxValue;
    76→        }
    77→    }
    78→
    79→    [MethodImpl(MethodImplOptions.NoInlining)]
    80→    private static long DataGasCostShortInternal(ReadOnlySpan<byte> inputData, IReleaseSpec releaseSpec)
    81→    {
    82→        Debug.Assert(inputData.Length < LengthsLengths);
    83→
    84→        Span<byte> extendedInput = stackalloc byte[LengthsLengths];
    85→        inputData.CopyTo(extendedInput);
    86→
    87→        return DataGasCostInternal(extendedInput, releaseSpec);
    88→    }
    89→
    90→    private static long DataGasCostInternal(ReadOnlySpan<byte> inputData, IReleaseSpec releaseSpec)
    91→    {
    92→        (uint baseLength, uint expLength, uint modulusLength) = GetInputLengths(inputData);
    93→        if (ExceedsMaxInputSize(releaseSpec, baseLength, expLength, modulusLength))
    94→        {
    95→            return long.MaxValue;
    96→        }
    97→
    98→        ulong complexity = MultComplexity(baseLength, modulusLength, releaseSpec.IsEip7883Enabled);
    99→
   100→        uint expLengthUpTo32 = Math.Min(LengthSize, expLength);
   101→        uint startIndex = LengthsLengths + baseLength; //+ expLength - expLengthUpTo32; // Geth takes head here, why?
   102→        UInt256 exp = new(inputData.SliceWithZeroPaddingEmptyOnError((int)startIndex, (int)expLengthUpTo32), isBigEndian: true);
   103→        UInt256 iterationCount = CalculateIterationCount(expLength, exp, releaseSpec.IsEip7883Enabled);
   104→
   105→        bool overflow = UInt256.MultiplyOverflow(complexity, iterationCount, out UInt256 result);
   106→
   107→        if (!releaseSpec.IsEip7883Enabled)
   108→        {
   109→            result /= 3;
   110→        }
   111→
   112→        return result > long.MaxValue || overflow
   113→            ? long.MaxValue
   114→            : Math.Max(releaseSpec.IsEip7883Enabled ? GasCostOf.MinModExpEip7883 : GasCostOf.MinModExpEip2565, (long)result);
   115→    }
   116→
   117→    private static bool ExceedsMaxInputSize(IReleaseSpec releaseSpec, uint baseLength, uint expLength, uint modulusLength)
   118→    {
   119→        return releaseSpec.IsEip7823Enabled
   120→            ? (baseLength > ModExpMaxInputSizeEip7823 | expLength > ModExpMaxInputSizeEip7823 | modulusLength > ModExpMaxInputSizeEip7823)
   121→            : (baseLength | modulusLength) > int.MaxValue;
   122→    }
   123→
   124→    [MethodImpl(MethodImplOptions.NoInlining)]
   125→    private (uint baseLength, uint expLength, uint modulusLength) GetInputLengthsShort(ReadOnlySpan<byte> inputData)
   126→    {
   127→        Debug.Assert(inputData.Length < LengthsLengths);
   128→
   129→        Span<byte> extendedInput = stackalloc byte[LengthsLengths];
   130→        inputData.CopyTo(extendedInput);
   131→
   132→        return GetInputLengths(extendedInput);
   133→    }
   134→
   135→    private static (uint baseLength, uint expLength, uint modulusLength) GetInputLengths(ReadOnlySpan<byte> inputData)
   136→    {
   137→        // Test if too high
   138→        if (Vector256<byte>.IsSupported)
   139→        {
   140→            ref var firstByte = ref MemoryMarshal.GetReference(inputData);
   141→            Vector256<byte> mask = ~Vector256.Create(0, 0, 0, 0, 0, 0, 0, uint.MaxValue).AsByte();
   142→            if (Vector256.BitwiseAnd(
   143→                    Vector256.BitwiseOr(
   144→                        Vector256.BitwiseOr(
   145→                            Unsafe.ReadUnaligned<Vector256<byte>>(ref firstByte),
   146→                            Unsafe.ReadUnaligned<Vector256<byte>>(ref Unsafe.Add(ref firstByte, StartExpLength))),
   147→                        Unsafe.ReadUnaligned<Vector256<byte>>(ref Unsafe.Add(ref firstByte, 64))),
   148→                mask) != Vector256<byte>.Zero)
   149→            {
   150→                return GetInputLengthsMayOverflow(inputData);
   151→            }
   152→        }
   153→        else if (Vector128<byte>.IsSupported)
   154→        {
   155→            ref var firstByte = ref MemoryMarshal.GetReference(inputData);
   156→            Vector128<byte> mask = ~Vector128.Create(0, 0, 0, uint.MaxValue).AsByte();
   157→            if (Vector128.BitwiseOr(
   158→                    Vector128.BitwiseOr(
   159→                        Vector128.BitwiseOr(
   160→                            Unsafe.ReadUnaligned<Vector128<byte>>(ref firstByte),
   161→                            Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartExpLength))),
   162→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, 64))),
   163→                    Vector128.BitwiseAnd(
   164→                        Vector128.BitwiseOr(
   165→                            Vector128.BitwiseOr(
   166→                                Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, 16)),
   167→                                Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartExpLength + 16))),
   168→                            Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartModLength + 16))),
   169→                        mask)
   170→                ) != Vector128<byte>.Zero)
   171→            {
   172→                return GetInputLengthsMayOverflow(inputData);
   173→            }
   174→        }
   175→        else if (inputData.Slice(StartBaseLength, LengthSize - sizeof(uint)).IndexOfAnyExcept((byte)0) >= 0 ||
   176→                inputData.Slice(StartExpLength, LengthSize - sizeof(uint)).IndexOfAnyExcept((byte)0) >= 0 ||
   177→                inputData.Slice(StartModLength, LengthSize - sizeof(uint)).IndexOfAnyExcept((byte)0) >= 0)
   178→        {
   179→            return GetInputLengthsMayOverflow(inputData);
   180→        }
   181→
   182→        uint baseLength = BinaryPrimitives.ReadUInt32BigEndian(inputData.Slice(32 - sizeof(uint), sizeof(uint)));
   183→        uint expLength = BinaryPrimitives.ReadUInt32BigEndian(inputData.Slice(64 - sizeof(uint), sizeof(uint)));
   184→        uint modulusLength = BinaryPrimitives.ReadUInt32BigEndian(inputData.Slice(96 - sizeof(uint), sizeof(uint)));
   185→        return (baseLength, expLength, modulusLength);
   186→    }
   187→
   188→    [MethodImpl(MethodImplOptions.NoInlining)]
   189→    private static (uint baseLength, uint expLength, uint modulusLength) GetInputLengthsMayOverflow(ReadOnlySpan<byte> inputData)
   190→    {
   191→        // Only valid if baseLength and modulusLength are zero; when expLength doesn't matter
   192→        if (Vector256<byte>.IsSupported)
   193→        {
   194→            ref var firstByte = ref MemoryMarshal.GetReference(inputData);
   195→            if (Vector256.BitwiseOr(
   196→                    Unsafe.ReadUnaligned<Vector256<byte>>(ref firstByte),
   197→                    Unsafe.ReadUnaligned<Vector256<byte>>(ref Unsafe.Add(ref firstByte, StartModLength)))
   198→                != Vector256<byte>.Zero)
   199→            {
   200→                // Overflow
   201→                return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
   202→            }
   203→        }
   204→        else if (Vector128<byte>.IsSupported)
   205→        {
   206→            ref var firstByte = ref MemoryMarshal.GetReference(inputData);
   207→            if (Vector128.BitwiseOr(
   208→                    Vector128.BitwiseOr(
   209→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref firstByte),
   210→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, 16))),
   211→                    Vector128.BitwiseOr(
   212→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartModLength)),
   213→                        Unsafe.ReadUnaligned<Vector128<byte>>(ref Unsafe.Add(ref firstByte, StartModLength + 16)))
   214→                ) != Vector128<byte>.Zero)
   215→            {
   216→                // Overflow
   217→                return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
   218→            }
   219→        }
   220→        else if (inputData.Slice(StartBaseLength, LengthSize).IndexOfAnyExcept((byte)0) >= 0 ||
   221→                inputData.Slice(StartModLength, LengthSize).IndexOfAnyExcept((byte)0) >= 0)
   222→        {
   223→            // Overflow
   224→            return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
   225→        }
   226→
   227→        return (0, uint.MaxValue, 0);
   228→    }
   229→
   230→    public unsafe (byte[], bool) Run(ReadOnlyMemory<byte> inputData, IReleaseSpec releaseSpec)
   231→    {
   232→        Metrics.ModExpPrecompile++;
   233→
   234→        ReadOnlySpan<byte> inputSpan = inputData.Span;
   235→        (uint baseLength, uint expLength, uint modulusLength) = inputSpan.Length >= LengthsLengths
   236→                ? GetInputLengths(inputSpan)
   237→                : GetInputLengthsShort(inputSpan);
   238→
   239→        if (ExceedsMaxInputSize(releaseSpec, baseLength, expLength, modulusLength))
   240→            return IPrecompile.Failure;
   241→
   242→        // if both are 0, then expLength can be huge, which leads to a potential buffer too big exception
   243→        if (baseLength == 0 && modulusLength == 0)
   244→            return (Bytes.Empty, true);
   245→
   246→        using var modulusInt = mpz_t.Create();
   247→
   248→        ReadOnlySpan<byte> modulusDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96 + (int)baseLength + (int)expLength, (int)modulusLength);
   249→        if (modulusDataSpan.Length > 0)
   250→        {
   251→            fixed (byte* modulusData = &MemoryMarshal.GetReference(modulusDataSpan))
   252→                Gmp.mpz_import(modulusInt, modulusLength, 1, 1, 1, nuint.Zero, (nint)modulusData);
   253→        }
   254→
   255→        if (Gmp.mpz_sgn(modulusInt) == 0)
   256→            return (new byte[modulusLength], true);
   257→
   258→        using var baseInt = mpz_t.Create();
   259→        using var expInt = mpz_t.Create();
   260→        using var powmResult = mpz_t.Create();
   261→
   262→        ReadOnlySpan<byte> baseDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96, (int)baseLength);
   263→        if (baseDataSpan.Length > 0)
   264→        {
   265→            fixed (byte* baseData = &MemoryMarshal.GetReference(baseDataSpan))
   266→                Gmp.mpz_import(baseInt, baseLength, 1, 1, 1, nuint.Zero, (nint)baseData);
   267→        }
   268→
   269→        ReadOnlySpan<byte> expDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96 + (int)baseLength, (int)expLength);
   270→        if (expDataSpan.Length > 0)
   271→        {
   272→            fixed (byte* expData = &MemoryMarshal.GetReference(expDataSpan))
   273→                Gmp.mpz_import(expInt, expLength, 1, 1, 1, nuint.Zero, (nint)expData);
   274→        }
   275→
   276→        Gmp.mpz_powm(powmResult, baseInt, expInt, modulusInt);
   277→
   278→        nint powmResultLen = (nint)(Gmp.mpz_sizeinbase(powmResult, 2) + 7) / 8;
   279→        nint offset = (int)modulusLength - powmResultLen;
   280→
   281→        byte[] result = new byte[modulusLength];
   282→        fixed (byte* ptr = &MemoryMarshal.GetArrayDataReference(result))
   283→            Gmp.mpz_export((nint)(ptr + offset), out _, 1, 1, 1, nuint.Zero, powmResult);
   284→
   285→        return (result, true);
   286→    }
   287→
   288→    /// <summary>
   289→    /// def calculate_multiplication_complexity(base_length, modulus_length):
   290→    /// max_length = max(base_length, modulus_length)
   291→    /// words = math.ceil(max_length / 8)
   292→    /// return words**2
   293→    /// </summary>
   294→    /// <returns></returns>
   295→    private static ulong MultComplexity(uint baseLength, uint modulusLength, bool isEip7883Enabled)
   296→    {
   297→        // Pick the larger of the two  
   298→        uint max = baseLength > modulusLength ? baseLength : modulusLength;
   299→
   300→        // Compute ceil(max/8) via a single add + shift
   301→        // (max + 7) >> 3  ==  (max + 7) / 8, rounding up
   302→        ulong words = ((ulong)max + 7u) >> 3;
   303→
   304→        // Square it once
   305→        ulong sq = words * words;
   306→
   307→        // If EIP-7883 => small-case = 16, else 2*sq when max>32
   308→        if (isEip7883Enabled)
   309→        {
   310→            return max > LengthSize
   311→                ? (sq << 1)    // 2 * words * words
   312→                : 16UL;        // constant floor
   313→        }
   314→
   315→        // Otherwise plain square
   316→        return sq;
   317→    }
   318→
   319→    static readonly ulong IterationCountMultiplierEip2565 = 8;
   320→
   321→    static readonly ulong IterationCountMultiplierEip7883 = 16;
   322→
   323→    /// <summary>
   324→    /// def calculate_iteration_count(exponent_length, exponent):
   325→    /// iteration_count = 0
   326→    /// if exponent_length &lt;= 32 and exponent == 0: iteration_count = 0
   327→    /// elif exponent_length &lt;= 32: iteration_count = exponent.bit_length() - 1
   328→    /// elif exponent_length > 32: iteration_count = (8 * (exponent_length - 32)) + ((exponent & (2**256 - 1)).bit_length() - 1)
   329→    /// return max(iteration_count, 1)
   330→    /// </summary>
   331→    /// <param name="exponentLength"></param>
   332→    /// <param name="exponent"></param>
   333→    /// <param name="isEip7883Enabled"></param>
   334→    /// <returns></returns>
   335→    private static UInt256 CalculateIterationCount(uint exponentLength, UInt256 exponent, bool isEip7883Enabled)
   336→    {
   337→        ulong iterationCount;
   338→        uint overflow = 0;
   339→        if (exponentLength <= LengthSize)
   340→        {
   341→            iterationCount = (uint)Math.Max(1, exponent.BitLen - 1);
   342→        }
   343→        else
   344→        {
   345→            uint bitLength = (uint)exponent.BitLen;
   346→            if (bitLength > 0)
   347→            {
   348→                bitLength--;
   349→            }
   350→
   351→            ulong multiplicationResult = (exponentLength - LengthSize) * (isEip7883Enabled ? IterationCountMultiplierEip7883 : IterationCountMultiplierEip2565);
   352→            iterationCount = multiplicationResult + bitLength;
   353→            if (iterationCount < multiplicationResult)
   354→            {
   355→                // Overflowed
   356→                overflow = 1;
   357→            }
   358→            else if (iterationCount < 1)
   359→            {
   360→                // Min 1 iteration
   361→                iterationCount = 1;
   362→            }
   363→        }
   364→
   365→        return new UInt256(iterationCount, overflow);
   366→    }
   367→}
   368→

